import { promises as fs } from 'fs';
import * as path from 'path';

/** Storage for uploaded files. The local disk implementation can be replaced (e.g. by S3) without touching callers. */
export abstract class FileStorage {
  abstract put(key: string, data: Buffer): Promise<void>;
  abstract read(key: string): Promise<Buffer | null>;
  abstract delete(key: string): Promise<void>;
}

/** Keys are generated by the server: a UUID plus a known image extension. Nothing else is ever accepted. */
export const STORAGE_KEY_REGEX =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png|webp)$/;

export class LocalFileStorage extends FileStorage {
  private readonly root: string;

  constructor(directory: string) {
    super();
    this.root = path.resolve(process.cwd(), directory);
  }

  async put(key: string, data: Buffer): Promise<void> {
    const target = this.resolve(key);
    await fs.mkdir(path.dirname(target), { recursive: true });
    await fs.writeFile(target, data, { mode: 0o640 });
  }

  async read(key: string): Promise<Buffer | null> {
    try {
      return await fs.readFile(this.resolve(key));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw error;
    }
  }

  async delete(key: string): Promise<void> {
    await fs.rm(this.resolve(key), { force: true });
  }

  private resolve(key: string): string {
    if (!STORAGE_KEY_REGEX.test(key)) throw new Error('Invalid storage key');
    const target = path.resolve(this.root, key);
    if (!target.startsWith(this.root + path.sep))
      throw new Error('Invalid storage key');
    return target;
  }
}
